ORDER_IDS = [oid.strip() for oid in RAW_ORDER_IDS.split(",") if oid.strip()]

# ---------- OUTPUT SETUP ----------
OUTPUT_DIR = "output"
os.makedirs(OUTPUT_DIR, exist_ok=True)

JSON_FILE = os.path.join(OUTPUT_DIR, "docpharma_responses.json")
EXCEL_FILE = os.path.join(OUTPUT_DIR, "docpharma_responses.xlsx")

responses = []
failed = []

print(f"--- Fetching {len(ORDER_IDS)} DocPharma Orders ---")

with app.app_context():

    if not app.config.get("DOCPHARMA_API_KEY"):
        app.config["DOCPHARMA_API_KEY"] = os.environ.get("DOCPHARMA_API_KEY")

    config = app.config

    for i, order_id in enumerate(ORDER_IDS, start=1):
        print(f"[{i}/{len(ORDER_IDS)}] {order_id}")

        try:
            result = fetch_docpharma_details(order_id, config)

            if result:
                responses.append({
                    "order_id": order_id,
                    "status": "success",
                    "data": result
                })
            else:
                failed.append(order_id)
                responses.append({
                    "order_id": order_id,
                    "status": "no_data",
                    "data": None
                })

        except Exception as e:
            failed.append(order_id)
            responses.append({
                "order_id": order_id,
                "status": "error",
                "error": str(e)
            })

# ---------- SAVE JSON ----------
with open(JSON_FILE, "w", encoding="utf-8") as f:
    json.dump(responses, f, indent=2, ensure_ascii=False)

print(f"\n✅ JSON saved: {JSON_FILE}")

# ---------- CONVERT JSON → EXCEL ----------
rows = []

for item in responses:
    base = {
        "order_id": item.get("order_id"),
        "status": item.get("status"),
    }

    data = item.get("data")

    if isinstance(data, dict):
        for key, value in data.items():
            base[key] = value
    else:
        base["response"] = data

    rows.append(base)

df = pd.DataFrame(rows)

df.to_excel(EXCEL_FILE, index=False)

print(f"✅ Excel saved: {EXCEL_FILE}")

# ---------- SUMMARY ----------
print("\n=========== SUMMARY ===========")
print(f"Total Orders : {len(ORDER_IDS)}")
print(f"Success      : {len([r for r in responses if r['status'] == 'success'])}")
print(f"Failed       : {len(failed)}")

if failed:
    print("\nFailed Order IDs:")
    for f in failed:
        print(f"- {f}")

print("\n--- DONE ---")
